    fn sample_shape() -> ShapeTree {
        ShapeTree {
            nodes: vec![aigent_protocol::ShapeNode {
                node_id: 1,
                parent_node_id: 0,
                transform: None,
                primitive: Some(Primitive::Box(BoxPrimitive {
                    size_x_mm: 1000,
                    size_y_mm: 1000,
                    size_z_mm: 1000,
                })),
                joint_name: None,
                color: None,
                material_tags: Vec::new(),
            }],
        }
    }

