    /// Pause or resume the outbound pump for a connection (test / stuck-writer).
    pub async fn set_outbound_paused(&self, connection_id: &[u8], paused: bool) -> bool {
        let sockets = self.sockets.lock().await;
        if let Some(live) = sockets.get(connection_id) {
            live.outbound_paused.store(paused, Ordering::Relaxed);
            true
        } else {
            false
        }
    }

    /// Non-blocking publish from the simulation stage.
    pub fn publish_generation(&self, generation: ImmutableGeneration) {
        self.mailbox.publish_from_tick(generation);
    }

    /// Client-initiated full snapshot resync without tearing down the socket.
    /// Preserves the connection's ordered-event cursor (protocol v1).
    pub async fn deliver_client_resync(&self, connection_id: &[u8]) -> bool {
        let generation = {
            let world = self.world.lock().await;
            world
                .last_generation()
                .cloned()
                .unwrap_or_else(|| ImmutableGeneration {
                    generation: 0,
                    tick: 0,
                    world_value: world.world_value(),
                    ruleset_generation_id: 0,
                    active_leases: Default::default(),
                    aigent_bodies: Default::default(),
                    applied_commands: Vec::new(),
                    expired_leases: Vec::new(),
                    lease_terminations: Vec::new(),
                    rng_draws: Vec::new(),
                    entities: world.entities().snapshots(),
                    next_entity_id: world.entities().next_entity_id(),
                })
        };

        // Build the body outside the lock so the byte measure reflects the
        // real frame the socket will receive. The fanout installs the body
        // on the snapshot channel but returns the bytes to charge against
        // the queue.
        let message_id = self.next_server_message_id();
        let (baseline_id, body) = {
            let mut fanout = self.fanout.lock().await;
            let measure = |shape: &crate::fanout::RealFrameShape<'_>| {
                let preview = match shape {
                    crate::fanout::RealFrameShape::Full { body, .. } => {
                        crate::wire::encode_world_snapshot_body(body)
                    }
                    _ => Vec::new(),
                };
                server_envelope(
                    connection_id,
                    message_id,
                    envelope::Body::FullSnapshot(FullSnapshot {
                        baseline_id: 0,
                        payload: preview,
                    }),
                )
                .encoded_len()
            };
            let Some((baseline_id, body, _events, _enqueue)) =
                fanout.client_resync_real(connection_id, &generation, &measure)
            else {
                return false;
            };
            if let Some(connection) = fanout.get_mut(connection_id) {
                connection.hold_observe = true;
            }
            (baseline_id, body)
        };
        let frame = encode_envelope(
            connection_id,
            message_id,
            envelope::Body::FullSnapshot(FullSnapshot {
                baseline_id,
                payload: crate::wire::encode_world_snapshot_body(&body),
            }),
        );
        let delivered = self.try_deliver(connection_id, Bytes::from(frame)).await;
        if delivered {
            // Only clear hold_observe once the full snapshot is actually on
            // the wire. A previous version cleared it unconditionally, which
            // left the connection stuck waiting for a baseline that never
            // installed.
            let mut fanout = self.fanout.lock().await;
            if let Some(connection) = fanout.get_mut(connection_id) {
                connection.hold_observe = false;
            }
        }
        delivered
    }

    /// Serialization-stage drain: observe prior undrained pressure, then encode
    /// observe traffic and try_send to sockets. Close only slow connections.
    /// Never awaits I/O. Queue byte accounting clears only after the socket
    /// task reports a send via [`Self::note_frame_sent`], so healthy writers
    /// that clear between ticks stay under the overflow window.
    ///
    /// `encoded_bytes` is a fixture override that charges every state item a
    /// fixed size. The production path passes `None`, and each item is then
    /// charged the exact encoded length of the frame this pass writes for it,
    /// so the 256 KiB coalesce threshold and the sustained-overflow disconnect
    /// (ARCHITECTURE section 1) measure real socket bytes.
    pub async fn drain_fanout(&self, encoded_bytes: Option<usize>) -> DrainReport {
        // Observe first: pressure is from frames not yet written (and therefore
        // not yet cleared by note_frame_sent), not from this pass's enqueue.
        let mut report = self.observe_only().await;
        let Some(generation) = self.mailbox.take() else {
            return report;
        };
        let ids: Vec<Vec<u8>> = {
            let fanout = self.fanout.lock().await;
            fanout.connection_ids()
        };
        let connection_aigents: HashMap<Vec<u8>, Vec<u8>> = {
            let sessions = self.sessions.lock().await;
            ids.iter()
                .filter_map(|connection_id| {
                    sessions
                        .aigent_id_for(connection_id)
                        .map(|aigent_id| (connection_id.clone(), aigent_id))
                })
                .collect()
        };
        let focus_updates: Vec<(Vec<u8>, u64)> = {
            let world = self.world.lock().await;
            connection_aigents
                .iter()
                .filter_map(|(connection_id, aigent_id)| {
                    let body_id = world.body_for_aigent(aigent_id)?;
                    Some((connection_id.clone(), body_id))
                })
                .collect()
        };
        if !focus_updates.is_empty() {
            let mut fanout = self.fanout.lock().await;
            for (connection_id, body_id) in focus_updates {
                if let Some(connection) = fanout.get_mut(&connection_id) {
                    connection.focus_body_id = Some(body_id);
                }
            }
        }
        let mut delivered = 0usize;
        for connection_id in ids {
            if report.closed.iter().any(|id| id == &connection_id) {
                continue;
            }
            self.flush_pending(&connection_id).await;
            // One message id per connection per pass: the id a frame is sized
            // with is the id it is written with, so the bytes charged to the
            // outbound queue are the bytes that reach the socket.
            let message_id = self.next_server_message_id();
            let measure = |shape: StateFrameShape<'_>| {
                state_frame_encoded_len(&connection_id, message_id, shape)
            };
            let _sizing = match encoded_bytes {
                Some(bytes) => StateSizing::Fixed(bytes),
                None => StateSizing::Frame(&measure),
            };
            // Publish and encode under one lock: a client resync arriving
            // between them would replace this connection's payload, so the
            // queue would be charged one frame while the socket received
            // another. No await happens inside, so the drain still never
            // blocks on I/O.
            //
            // task-054: live traffic now uses the real-body publish path,
            // which reads AOI candidates from the entity store and emits
            // `WorldSnapshotBody` / `WorldSnapshotDelta` instead of the
            // legacy `AIGB` placeholder.
            let (outcome, frames) = {
                let mut fanout = self.fanout.lock().await;
                let real_measure = |shape: &crate::fanout::RealFrameShape<'_>| {
                    // Test/pressure fixtures may pass a fixed byte override
                    // to model the legacy "charge a stand-in size" path
                    // (e.g. sustained-overflow isolation). When set, every
                    // state item is charged that size; the production path
                    // measures the real wire frame.
                    if let Some(fixed) = encoded_bytes {
                        return fixed;
                    }
                    state_frame_encoded_len_real(&connection_id, message_id, *shape)
                };
                let Some(outcome) =
                    fanout.publish_real_interest_to(&connection_id, &generation, &real_measure)
                else {
                    continue;
                };
                let frames = encode_real_publish_frames(&connection_id, message_id, &outcome);
                (outcome, frames)
            };
            if let Some(aigent_id) = connection_aigents.get(&connection_id) {
                for termination in generation
                    .lease_terminations
                    .iter()
                    .filter(|termination| &termination.aigent_id == aigent_id)
                {
                    let reason = match termination.reason {
                        crate::lease::LeaseTerminationReason::Blocked => {
                            ProtoLeaseTerminationReason::Blocked
                        }
                        crate::lease::LeaseTerminationReason::Expired => {
                            ProtoLeaseTerminationReason::Expired
                        }
                        crate::lease::LeaseTerminationReason::Cancelled => {
                            ProtoLeaseTerminationReason::Cancelled
                        }
                        crate::lease::LeaseTerminationReason::Ruleset => {
                            ProtoLeaseTerminationReason::Ruleset
                        }
                        crate::lease::LeaseTerminationReason::Invalidated => {
                            ProtoLeaseTerminationReason::Invalidated
                        }
                    };
                    let frame = encode_envelope(
                        &connection_id,
                        self.next_server_message_id(),
                        envelope::Body::Percept(Percept {
                            kind: PerceptKind::LeaseTerminated as i32,
                            payload: LeaseTerminatedPayload {
                                body_id: termination.body_id,
                                reason: reason as i32,
                                conflicting_entity_id: termination.conflicting_entity_id,
                            }
                            .encode_to_vec(),
                        }),
                    );
                    let queued = {
                        let mut fanout = self.fanout.lock().await;
                        fanout
                            .get_mut(&connection_id)
                            .is_some_and(|connection| connection.queue.enqueue_event(frame.len()))
                    };
                    if queued && self.try_deliver(&connection_id, Bytes::from(frame)).await {
                        delivered += 1;
                    }
                }
            }
            if let RealPublishOutcome::InterestUnavailable { error } = outcome {
                report
                    .interest_unavailable
                    .push((connection_id.clone(), error));
                continue;
            }
            for frame in frames {
                if self.try_deliver(&connection_id, Bytes::from(frame)).await {
                    delivered += 1;
                }
            }
        }
        report.delivered = delivered;
        report
    }

