import * as THREE from "three";
import { create, fromBinary, toBinary } from "@bufbuild/protobuf";
import {
  ClientHelloSchema,
  ConnectionRole,
  EnvelopeSchema,
  HandshakeFrameSchema,
  SnapshotResyncRequestSchema,
} from "@aigent-place/protocol";
import {
  decodeWorldSnapshotBody,
  decodeWorldSnapshotDelta,
} from "./wire/real-snapshot.js";

const status = document.querySelector("#status");
const canvas = document.querySelector("#viewport");

function mmToMeters(mm) {
  return Number(mm) / 1000;
}

function setStatus(text) {
  if (status) {
    status.textContent = text;
  }
}

function createSmokeScene(targetCanvas) {
  const renderer = new THREE.WebGLRenderer({ canvas: targetCanvas, antialias: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.setSize(targetCanvas.clientWidth, targetCanvas.clientHeight, false);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0b0d12);
  const camera = new THREE.PerspectiveCamera(
    60,
    targetCanvas.clientWidth / Math.max(1, targetCanvas.clientHeight),
    0.1,
    1000,
  );
  camera.position.set(8, 6, 10);
  camera.lookAt(0, 0, 0);
  const ambient = new THREE.AmbientLight(0xffffff, 0.6);
  scene.add(ambient);
  const directional = new THREE.DirectionalLight(0xffffff, 0.4);
  directional.position.set(5, 10, 7);
  scene.add(directional);
  const cube = new THREE.Mesh(
    new THREE.BoxGeometry(1, 1, 1),
    new THREE.MeshStandardMaterial({ color: 0x4f8cff }),
  );
  scene.add(cube);
  return { renderer, scene, camera, cube };
}

/**
 * Live spectator that decodes `WorldSnapshotBodyProto` /
 * `WorldSnapshotDeltaProto` from the server and renders one Three.js
 * mesh per entity. Actual visual mesh selection from the shape tree
 * is task-055; this card wires the decoder in lockstep with the
 * server encoder.
 */
export function startLiveViewer(targetCanvas, wsUrl) {
  const { renderer, scene, camera } = createSmokeScene(targetCanvas);
  const smoke = scene.children.find((child) => child.isMesh);
  if (smoke) {
    scene.remove(smoke);
  }

  /** @type {Map<string, { mesh: THREE.Mesh, target: THREE.Vector3 }>} */
  const bodies = new Map();
  let baselineId = null;
  let waitingForFull = true;
  let handshakeDone = false;
  let lastTick = 0n;
  let socket = null;
  let closed = false;
  /** @type {Uint8Array | null} */
  let connectionId = null;
  let nextMessageId = 1n;
  /** @type {Set<string>} */
  const seen = new Set();

  function removeMissing() {
    for (const [key, entry] of bodies) {
      if (!seen.has(key)) {
        scene.remove(entry.mesh);
        entry.mesh.geometry.dispose();
        entry.mesh.material.dispose();
        bodies.delete(key);
      }
    }
  }

  function upsertBody(entityId, xMm, yMm, zMm) {
    const key = entityId.toString();
    seen.add(key);
    const target = new THREE.Vector3(mmToMeters(xMm), mmToMeters(yMm), mmToMeters(zMm));
    let entry = bodies.get(key);
    if (!entry) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(1, 1, 1),
        new THREE.MeshStandardMaterial({ color: 0x4f8cff }),
      );
      mesh.position.copy(target);
      scene.add(mesh);
      entry = { mesh, target };
      bodies.set(key, entry);
    }
    entry.target.copy(target);
  }

  function requestResync(reason) {
    waitingForFull = true;
    baselineId = null;
    if (!socket || socket.readyState !== WebSocket.OPEN || !connectionId) {
      setStatus(`viewer: ${reason} �?" reconnecting for full snapshot`);
      socket?.close();
      return;
    }
    setStatus(`viewer: ${reason} �?" requesting full snapshot`);
    const messageId = nextMessageId;
    nextMessageId += 1n;
    socket.send(
      toBinary(
        EnvelopeSchema,
        create(EnvelopeSchema, {
          protocolMajor: 1,
          connectionId,
          messageId,
          metadata: {},
          body: {
            case: "snapshotResyncRequest",
            value: create(SnapshotResyncRequestSchema, {}),
          },
        }),
      ),
    );
  }

  function applyBody(record) {
    upsertBody(
      record.entityId,
      record.positionMm.x,
      record.positionMm.y,
      record.positionMm.z,
    );
  }

  function handleEnvelope(bytes) {
    const envelope = fromBinary(EnvelopeSchema, bytes);
    if (envelope.protocolMajor !== 1) {
      setStatus(`viewer: unsupported protocol major ${envelope.protocolMajor}`);
      return;
    }
    const body = envelope.body;
    if (body.case === "fullSnapshot") {
      baselineId = body.value.baselineId;
      waitingForFull = false;
      const decoded = decodeWorldSnapshotBody(body.value.payload);
      if (!decoded) {
        // Unknown version or malformed payload: do not trust the
        // baseline_id and ask for a resync instead.
        setStatus("viewer: full snapshot version unknown or payload malformed �?" requesting resync");
        requestResync("snapshot version unknown");
        return;
      }
      lastTick = decoded.tick;
      seen.clear();
      for (const record of decoded.bodies) {
        applyBody(record);
      }
      removeMissing();
      setStatus(
        `viewer: live tick=${decoded.tick} bodies=${decoded.bodies.length} (real bodies)`,
      );
      return;
    }
    if (body.case === "snapshotDelta") {
      if (waitingForFull || baselineId === null) {
        return;
      }
      if (body.value.baselineId !== baselineId) {
        requestResync("baseline mismatch");
        return;
      }
      const decoded = decodeWorldSnapshotDelta(body.value.payload);
      if (decoded) {
        for (const record of decoded.entered) {
          applyBody(record);
        }
        for (const record of decoded.modified) {
          applyBody(record);
        }
        for (const leftId of decoded.leftIds) {
          const key = leftId.toString();
          if (bodies.has(key)) {
            const entry = bodies.get(key);
            scene.remove(entry.mesh);
            entry.mesh.geometry.dispose();
            entry.mesh.material.dispose();
            bodies.delete(key);
          }
        }
        setStatus(
          `viewer: delta tick=${lastTick} bodies=${bodies.size} (real bodies, +${decoded.entered.length}/~${decoded.modified.length}/-${decoded.leftIds.length})`,
        );
      }
      return;
    }
    if (body.case === "snapshotResyncRequired") {
      requestResync("server resync required");
    }
  }

  function connect() {
    if (closed) {
      return;
    }
    handshakeDone = false;
    waitingForFull = true;
    baselineId = null;
    connectionId = null;
    // Drop any bodies carried over from a prior connection: a new
    // connection_id is a new session, the prior bodies are no longer
    // authoritative.
    for (const entry of bodies.values()) {
      scene.remove(entry.mesh);
      entry.mesh.geometry.dispose();
      entry.mesh.material.dispose();
    }
    bodies.clear();
    seen.clear();
    setStatus(`viewer: connecting ${wsUrl}`);
    socket = new WebSocket(wsUrl);
    socket.binaryType = "arraybuffer";
    socket.addEventListener("open", () => {
      const hello = create(ClientHelloSchema, {
        role: ConnectionRole.VIEWER,
        offeredProtocolMajors: [1],
        offeredFeatures: [],
        aigentId: new Uint8Array(),
      });
      socket.send(
        toBinary(
          HandshakeFrameSchema,
          create(HandshakeFrameSchema, {
            body: { case: "clientHello", value: hello },
          }),
        ),
      );
    });
    socket.addEventListener("message", (event) => {
      const data = event.data;
      const bytes =
        data instanceof ArrayBuffer
          ? new Uint8Array(data)
          : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
      if (!handshakeDone) {
        try {
          const frame = fromBinary(HandshakeFrameSchema, bytes);
          if (frame.body.case === "serverHello") {
            handshakeDone = true;
            connectionId = frame.body.value.connectionId;
            setStatus(
              `viewer: handshake ok major=${frame.body.value.selectedProtocolMajor} �?" waiting for snapshots`,
            );
            return;
          }
          if (frame.body.case === "handshakeReject") {
            setStatus(`viewer: handshake rejected: ${frame.body.value.reason}`);
            closed = true;
            socket?.close();
            return;
          }
        } catch {
          setStatus("viewer: malformed handshake frame");
          return;
        }
        return;
      }
      try {
        handleEnvelope(bytes);
      } catch (error) {
        setStatus(`viewer: envelope decode error: ${error?.message ?? error}`);
        // A malformed frame breaks the live delta chain. Treat it the
        // same as an unknown version: ask the server for a fresh full
        // snapshot.
        requestResync("malformed frame");
      }
    });
    socket.addEventListener("close", () => {
      if (closed) return;
      setStatus("viewer: socket closed �?" reconnecting");
      setTimeout(connect, 1000);
    });
    socket.addEventListener("error", () => {
      setStatus("viewer: socket error");
    });
  }

  connect();

  function tick() {
    for (const entry of bodies.values()) {
      entry.mesh.position.lerp(entry.target, 0.2);
    }
    renderer.render(scene, camera);
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

if (canvas instanceof HTMLCanvasElement) {
  const params = new URLSearchParams(location.search);
  const ws = params.get("ws") ?? "ws://127.0.0.1:7600/ws";
  startLiveViewer(canvas, ws);
}

//! AOI truncation on the live WebSocket fan-out path (task-044).
//!
//! task-016 built nearest-first interest truncation, but nothing on the live
//! path called it: `drain_fanout` encoded every active lease with every focus
//! pinned at the world origin. These tests assert the bytes a connected client
//! actually receives, so they fail against that path.
//!
//! The expected survivor set is derived here from the generation's own lease
//! table and the ARCHITECTURE A1 rule (nearest-first Euclidean truncation under
//! the hard cap, ties by ascending body id). It deliberately does not call the
//! production ranking helper: an oracle that reused `truncate_nearest` could
//! not fail when the ranking itself is wrong.

use std::collections::BTreeMap;
use std::sync::Arc;
use std::time::Duration;

use aigent_protocol::{
    command_result, envelope, handshake_frame, ClientHello, Command, CommandKind, CommandMetadata,
    ConnectionRole, Envelope, HandshakeFrame, MovePayload, ServerHello, SnapshotResyncRequest,
};
use futures_util::{SinkExt, StreamExt};
use prost::Message;
use tokio_tungstenite::tungstenite::Message as WsMessage;
use world_server::{
    decode_world_snapshot_body_ids, decode_world_snapshot_delta_left_ids,
    placeholder_body_from_lease, serve_ephemeral, AoiError, EntitySnapshot, ImmutableGeneration,
    LeaseSnapshot, Position, RealFrameShape, SessionHub, ShapeSlot, SnapshotFanout, TransportState,
    AOI_HARD_CAP, FIRST_ENTITY_ID, VIEWER_AOI_CAPS,
};

type Socket =
    tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;

/// Enough bodies to exceed the hard cap; the crowd plus the near band stays
/// under `2 * AOI_HARD_CAP`, so the direct truncation path is under test rather
/// than the dense spatial-hash gather.
const CROWD: std::ops::RangeInclusive<u64> = 1..=150;

/// Body ids whose placeholder poses sit near the world origin, so adding them
/// evicts part of the crowd from an origin-focused interest set.
const NEAR_ORIGIN_BAND: std::ops::RangeInclusive<u64> = 800..=839;

const WORLD_ORIGIN: (f64, f64, f64) = (0.0, 0.0, 0.0);

fn client_hello(role: ConnectionRole, aigent_id: &[u8]) -> Vec<u8> {
    HandshakeFrame {
        body: Some(handshake_frame::Body::ClientHello(ClientHello {
            role: role as i32,
            offered_protocol_majors: vec![1],
            offered_features: vec![],
            aigent_id: aigent_id.to_vec(),
        })),
    }
    .encode_to_vec()
}

async fn connect(url: &str, role: ConnectionRole, aigent_id: &[u8]) -> (Socket, ServerHello) {
    let (mut ws, _) = tokio_tungstenite::connect_async(url)
        .await
        .expect("connect");
    ws.send(WsMessage::Binary(client_hello(role, aigent_id).into()))
        .await
        .expect("send hello");
    let reply = ws.next().await.expect("reply").expect("stream ok");
    let WsMessage::Binary(bytes) = reply else {
        panic!("expected a binary ServerHello");
    };
    let frame = HandshakeFrame::decode(bytes.as_ref()).expect("handshake frame");
    match frame.body {
        Some(handshake_frame::Body::ServerHello(hello)) => (ws, hello),
        other => panic!("expected ServerHello, got {other:?}"),
    }
}

async fn start_server() -> (Arc<TransportState>, String) {
    let state = TransportState::new(SessionHub::new_v1());
    let (addr, server) = serve_ephemeral(Arc::clone(&state)).await.expect("bind");
    tokio::spawn(async move {
        let _ = server.await;
    });
    (state, format!("ws://{addr}/ws"))
}

async fn next_envelope(ws: &mut Socket) -> Envelope {
    let message = tokio::time::timeout(Duration::from_secs(5), ws.next())
        .await
        .expect("frame before timeout")
        .expect("stream open")
        .expect("frame ok");
    let WsMessage::Binary(bytes) = message else {
        panic!("expected a binary envelope");
    };
    Envelope::decode(bytes.as_ref()).expect("envelope")
}

/// Whether an observe frame was a full snapshot, plus the body ids it carried
/// in wire order, given the prior cumulative set. Command results and other
/// traffic are skipped.
///
/// A full snapshot replaces `prior`. A delta subtracts the explicit `left_ids`
/// and merges the union of `entered` and `modified`; the returned set is
/// `prior` updated with that diff.
async fn next_state_body_ids(ws: &mut Socket, prior: &[u64]) -> (bool, Vec<u64>) {
    for _ in 0..64 {
        match next_envelope(ws).await.body {
            Some(envelope::Body::FullSnapshot(full)) => {
                let ids = decode_world_snapshot_body_ids(&full.payload)
                    .expect("real-body snapshot payload");
                return (true, ids);
            }
            Some(envelope::Body::SnapshotDelta(delta)) => {
                let left = decode_world_snapshot_delta_left_ids(&delta.payload)
                    .expect("real-body delta payload");
                let em = decode_world_snapshot_entered_modified_ids(&delta.payload);
                let mut next: Vec<u64> = prior
                    .iter()
                    .copied()
                    .filter(|id| !left.contains(id))
                    .collect();
                if let Some(em) = em {
                    for id in em {
                        if !next.contains(&id) {
                            next.push(id);
                        }
                    }
                    next.sort();
                }
                return (false, next);
            }
            _ => continue,
        }
    }
    panic!("no snapshot or delta frame arrived");
}

/// Extract the union of `entered` and `modified` entity ids from a delta wire
/// payload. Returns `None` if the payload is not a `WorldSnapshotDeltaProto`.
fn decode_world_snapshot_entered_modified_ids(bytes: &[u8]) -> Option<Vec<u64>> {
    use prost::Message;
    let proto = aigent_protocol::WorldSnapshotDeltaProto::decode(bytes).ok()?;
    if proto.version != 1 {
        return None;
    }
    let mut ids: Vec<u64> = proto
        .entered
        .iter()
        .map(|b| b.entity_id)
        .chain(proto.modified.iter().map(|b| b.entity_id))
        .collect();
    ids.sort();
    ids.dedup();
    Some(ids)
}

fn lease(body_id: u64) -> LeaseSnapshot {
    LeaseSnapshot {
        body_id,
        aigent_id: format!("crowd-{body_id}").into_bytes(),
        sequence: 1,
        granted_tick: 1,
        expire_tick: 10_000,
        target_x_mm: 0,
        target_z_mm: 0,
        speed_mm_per_s: 1_000,
        consecutive_no_progress_ticks: 0,
    }
}

fn generation_of(
    tick: u64,
    leases: impl IntoIterator<Item = LeaseSnapshot>,
) -> ImmutableGeneration {
    let mut active_leases = BTreeMap::new();
    let mut entities = BTreeMap::new();
    for lease in leases {
        let body = placeholder_body_from_lease(&lease);
        let position = Position::new(
            body.x_mm as f64 / 1000.0,
            body.y_mm as f64 / 1000.0,
            body.z_mm as f64 / 1000.0,
        )
        .expect("placeholder position is within world bounds");
        entities.insert(
            lease.body_id,
            EntitySnapshot {
                entity_id: lease.body_id,
                revision: 1,
                position,
                shape: Some(ShapeSlot::from_encoded(
                    aigent_protocol::ShapeTree { nodes: Vec::new() }.encode_to_vec(),
                )),
            },
        );
        active_leases.insert(lease.body_id, lease);
    }
    ImmutableGeneration {
        generation: tick,
        tick,
        world_value: 0,
        ruleset_generation_id: 1,
        active_leases,
        aigent_bodies: Default::default(),
        applied_commands: vec![],
        expired_leases: vec![],
        lease_terminations: vec![],
        rng_draws: vec![],
        entities,
        next_entity_id: FIRST_ENTITY_ID,
    }
}

fn crowd_generation(tick: u64) -> ImmutableGeneration {
    generation_of(tick, CROWD.map(lease))
}

/// Pose in canonical metres, read from the entity table so the oracle does
/// not borrow the production AOI ranking helper.
fn pose_of(generation: &ImmutableGeneration, body_id: u64) -> (f64, f64, f64) {
    let entity = generation
        .entities
        .get(&body_id)
        .expect("body has an entity record in this generation");
    (
        entity.position.x(),
        entity.position.y(),
        entity.position.z(),
    )
}

/// Survivors the AOI contract requires for this generation and focus: the
/// `cap` nearest bodies by Euclidean distance, ties broken by ascending id.
fn expected_interest(
    generation: &ImmutableGeneration,
    focus: (f64, f64, f64),
    cap: usize,
) -> Vec<u64> {
    let mut ranked: Vec<(u64, f64)> = generation
        .active_leases
        .keys()
        .map(|&body_id| {
            let (x, y, z) = pose_of(generation, body_id);
            let (dx, dy, dz) = (x - focus.0, y - focus.1, z - focus.2);
            (body_id, dx * dx + dy * dy + dz * dz)
        })
        .collect();
    ranked.sort_by(|left, right| {
        left.1
            .partial_cmp(&right.1)
            .expect("finite distances")
            .then(left.0.cmp(&right.0))
    });
    ranked
        .into_iter()
        .take(cap)
        .map(|(body_id, _)| body_id)
        .collect()
}

fn hard_cap() -> usize {
    AOI_HARD_CAP as usize
}

/// Issue a real wire MOVE and wait for its authoritative acceptance, so the
/// world grants this aigent a body on the next tick.
async fn move_and_confirm(ws: &mut Socket, hello: &ServerHello, idempotency_key: &[u8]) {
    let command = Envelope {
        protocol_major: 1,
        connection_id: hello.connection_id.clone(),
        message_id: 1,
        metadata: Some(aigent_protocol::EnvelopeMetadata {
            required_features: vec![],
        }),
        body: Some(envelope::Body::Command(Command {
            metadata: Some(CommandMetadata {
                session_epoch: hello.session_epoch.clone(),
                sequence: 1,
                idempotency_key: idempotency_key.to_vec(),
            }),
            kind: CommandKind::Move as i32,
            payload: MovePayload {
                target_x_mm: 5_000,
                target_z_mm: 0,
                speed_mm_per_s: 1_000,
            }
            .encode_to_vec(),
        })),
    }
    .encode_to_vec();
    ws.send(WsMessage::Binary(command.into()))
        .await
        .expect("send move");
    match next_envelope(ws).await.body {
        Some(envelope::Body::CommandResult(result)) => assert!(
            matches!(result.outcome, Some(command_result::Outcome::Accepted(_))),
            "the move must be accepted before a lease can exist"
        ),
        other => panic!("expected a CommandResult, got {other:?}"),
    }
}

/// Advance the authoritative world one tick and clone what it published.
async fn advance_and_publish(state: &TransportState) -> ImmutableGeneration {
    let mut world = state.world.lock().await;
    world.advance_tick().expect("advance one tick");
    world
        .last_generation()
        .expect("published generation")
        .clone()
}

#[tokio::test]
async fn live_viewer_snapshot_truncates_to_the_hard_cap_nearest_first() {
    let (state, url) = start_server().await;
    let (mut viewer, _hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    let generation = crowd_generation(1);
    assert!(
        generation.active_leases.len() > hard_cap(),
        "the crowd must exceed the hard cap or this test asserts nothing"
    );
    state.publish_generation(generation.clone());
    let report = state.drain_fanout(None).await;
    assert_eq!(report.delivered, 1, "the viewer should receive one frame");

    let (is_full, delivered) = next_state_body_ids(&mut viewer, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered.len(),
        hard_cap(),
        "a live viewer snapshot must be truncated to the AOI hard cap"
    );
    assert_eq!(
        delivered,
        expected_interest(&generation, WORLD_ORIGIN, hard_cap()),
        "delivered bodies must be the nearest-first survivors for the viewer focus"
    );
}

#[tokio::test]
async fn live_aigent_interest_ranks_from_its_own_body() {
    let (state, url) = start_server().await;
    let aigent_id = b"aoi-focus-aigent".to_vec();
    let (mut aigent, hello) = connect(&url, ConnectionRole::Aigent, &aigent_id).await;

    // Take the aigent's own body from authoritative state rather than
    // re-deriving the server's aigent�+'body mapping: issue a real MOVE, advance
    // the world, and read back the lease the world granted to this aigent.
    move_and_confirm(&mut aigent, &hello, b"aoi-focus-move").await;
    let published = advance_and_publish(&state).await;
    let mut owned: Vec<LeaseSnapshot> = published
        .active_leases
        .values()
        .filter(|lease| lease.aigent_id == aigent_id)
        .cloned()
        .collect();
    assert_eq!(
        owned.len(),
        1,
        "the move should grant this aigent exactly one body"
    );
    let own_lease = owned.pop().expect("checked length");
    let own_body = own_lease.body_id;

    let generation = generation_of(2, CROWD.map(lease).chain(std::iter::once(own_lease)));
    let from_own_body = expected_interest(&generation, pose_of(&generation, own_body), hard_cap());
    let from_origin = expected_interest(&generation, WORLD_ORIGIN, hard_cap());
    assert_ne!(
        from_own_body, from_origin,
        "fixture must separate the aigent's body from the origin, or the test proves nothing"
    );

    state.publish_generation(generation.clone());
    let report = state.drain_fanout(None).await;
    assert_eq!(report.delivered, 1);

    let (is_full, delivered) = next_state_body_ids(&mut aigent, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered.first().copied(),
        Some(own_body),
        "an aigent's own body is at distance zero from its focus"
    );
    assert_eq!(
        delivered, from_own_body,
        "aigent interest must rank against its own body, not the world origin"
    );
}

#[tokio::test]
async fn bodies_leaving_the_interest_set_stop_appearing_in_deltas() {
    let (state, url) = start_server().await;
    let (mut viewer, _hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    let first = crowd_generation(1);
    state.publish_generation(first.clone());
    let _ = state.drain_fanout(None).await;
    let (is_full, delivered_first) = next_state_body_ids(&mut viewer, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered_first,
        expected_interest(&first, WORLD_ORIGIN, hard_cap())
    );

    // A band of bodies nearer the viewer focus displaces part of the crowd.
    let second = generation_of(2, CROWD.chain(NEAR_ORIGIN_BAND).map(lease));
    let expected_second = expected_interest(&second, WORLD_ORIGIN, hard_cap());
    let leaving: Vec<u64> = delivered_first
        .iter()
        .copied()
        .filter(|body_id| !expected_second.contains(body_id))
        .collect();
    assert!(
        !leaving.is_empty(),
        "fixture must evict at least one body, or the leave assertion is vacuous"
    );

    state.publish_generation(second.clone());
    let _ = state.drain_fanout(None).await;
    let (is_full, delivered_second) = next_state_body_ids(&mut viewer, &delivered_first).await;
    assert!(
        !is_full,
        "an established baseline should be followed by a delta"
    );
    // The new real-body delta carries explicit enter/modify/leave records, not
    // a full body list. After the test helper applies the diff to the prior
    // set, the cumulative set must match the expected AOI rank; the helper
    // returns it in ascending order, so compare via a sorted equal.
    let mut sorted_second = delivered_second.clone();
    sorted_second.sort();
    let mut sorted_expected = expected_second.clone();
    sorted_expected.sort();
    assert_eq!(
        sorted_second, sorted_expected,
        "after applying the delta, the cumulative interest set must match the truncated baseline"
    );
    for body_id in leaving {
        assert!(
            !sorted_second.contains(&body_id),
            "body {body_id} left the interest set and must stop being delivered"
        );
    }
}

#[tokio::test]
