            if matches!(outcome, ObserveOutcome::Closed { .. }) {
                closed.push(connection_id.clone());
                let sockets = self.sockets.lock().await;
                if let Some(live) = sockets.get(&connection_id) {
                    let _ = live.close_tx.send(true);
                }
            }
        }
